const item = $input.item.json;

const managerName = (item['Manager'] || '').toString().trim();
const greeting = managerName ? `Hi ${managerName}` : 'Hi Manager';

const rawService = (item['Service Pitch'] || '').toString().trim().toLowerCase();
const isAI = rawService.includes('ai');

const pitchInstruction = isAI
  ? `Write a short, persuasive cold outreach email offering to build a custom AI Agent for ${item['Business Name']}, a dental practice. Explain how the AI agent can handle patient inquiries, appointment booking, and follow-ups automatically, saving staff time and improving patient experience. Keep it under 130 words.`
  : `Write a short, persuasive cold outreach email offering to build or redesign a professional website for ${item['Business Name']}, a dental practice. Explain how a modern website attracts new patients, builds trust, and makes online booking easy. Keep it under 130 words.`;

const subject = isAI
  ? `A Smarter Way for ${item['Business Name']} to Handle Patient Calls`
  : `A New Website That Brings More Patients to ${item['Business Name']}`;

return {
  json: {
    businessName: item['Business Name'],
    phone: item['Phone'],
    email: item['Email Sender'],
    manager: managerName,
    greeting,
    servicePitch: item['Service Pitch'],
    pitchInstruction,
    subject
  }
};

values.content:
={{ $json.pitchInstruction }}

The greeting to use is: {{ $json.greeting }}

Write like a real person casually emailing a business owner — not like a marketing campaign. Avoid words like "free", "offer", "guarantee", "amazing", and avoid exclamation marks. Keep it short, warm, and direct — like a human wrote it in 2 minutes, not a template.

Do not include a subject line. Do not include any closing, sign-off, or signature of any kind — no "Best regards", no "Sincerely", no name placeholder, nothing after the last sentence of the email body. The email must end immediately after the final sentence.

Start with the greeting on its own line, then a blank line, then the body only.

