// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let text = $json.content.parts[0].text.trim();

// Signature hatayein agar AI ne khud add ki ho
text = text.replace(/\n*(Best regards|Sincerely|Regards|Warm regards|Thanks,?)[\s\S]*$/i, '').trim();

// Paragraphs ko single line banayein (mid-sentence breaks hatayein)
let paragraphs = text.split(/\n\s*\n/);
paragraphs = paragraphs.map(p => p.replace(/\n/g, ' ').trim());

// HTML paragraphs banayein - <p> tags har wrapping issue ko khatam kar dete hain
let html = paragraphs.map(p => `<p>${p}</p>`).join('');

return { json: { ...$json, cleanedHtml: html } };
